"""Semantic version sorting."""

from collections.abc import Iterable
from typing import TypeAlias

_IdentifierKey: TypeAlias = tuple[int, int | str]
_PrereleaseKey: TypeAlias = tuple[int, tuple[_IdentifierKey, ...]]
_VersionKey: TypeAlias = tuple[int, int, int, _PrereleaseKey]


def _identifier_key(identifier: str) -> _IdentifierKey:
    # SemVer numeric identifiers are ASCII digits; they sort before alphanumeric ones.
