        return 0, int(identifier)
    return 1, identifier


def _prerelease_key(prerelease: str | None) -> _PrereleaseKey:
    # A version without a pre-release sorts above any with one.
    if prerelease is None:
        return 1, ()
    return 0, tuple(_identifier_key(identifier) for identifier in prerelease.split('.'))


def _version_key(version: str) -> _VersionKey:
    # Build metadata after '+' is ignored for precedence.
    core = version.partition('+')[0]
    core, separator, prerelease = core.partition('-')
    major, minor, patch = (int(part) for part in core.split('.'))
    return major, minor, patch, _prerelease_key(prerelease if separator else None)


def sort_versions(vs: Iterable[str]) -> list[str]:
    """Return semantic version strings sorted by SemVer 2.0.0 precedence, lowest first.

    Build metadata is ignored for ordering, and versions that tie keep their input order.
